import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import SimpleButton from '../components/SimpleButton';

const SimpleResearchInsights = () => {
  const navigate = useNavigate();
  const [researchData, setResearchData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const loadResearchData = async () => {
      try {
        // First check if we have AI analysis from uploaded file
        const storedCompanyData = localStorage.getItem('companyData');

        if (storedCompanyData) {
          const companyData = JSON.parse(storedCompanyData);
          console.log('Research: Using AI analysis from upload');

          // Generate dynamic research data based on company
          const dynamicResearchData = generateDynamicResearchData(companyData);
          setResearchData(dynamicResearchData);
          console.log('Research: Dynamic research data generated');
        } else {
          // Fallback to default research data
          const defaultResearchData = {
            company: 'Unknown Company',
            research_summary: {
              news_sentiment: {
                sentiment: 'Neutral',
                score: 0.0,
                total_articles_analyzed: 0
              },
              litigation_data: {
                risk_assessment: 'Medium',
                total_cases: 0,
                active_cases: 0
              },
              industry_analysis: {
                outlook: 'Stable',
                growth_rate: 'Unknown',
                market_position: 'Unknown'
              },
              risk_signals: []
            }
          };
          setResearchData(defaultResearchData);
        }
      } catch (err) {
        console.error('Research: Error loading data:', err);
        setError('Failed to load research data: ' + err.message);
      } finally {
        setLoading(false);
      }
    };

    loadResearchData();
  }, [navigate]);

  // Generate dynamic research data based on company information
  const generateDynamicResearchData = (companyData) => {
    const company = companyData.company || 'Unknown Company';
    const revenue = companyData.revenue || 0;
    const profit = companyData.profit || 0;

    // Generate company-specific data based on hash
    const companyHash = company.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);

    // Dynamic sentiment based on profitability
    const profitMargin = profit / Math.max(revenue, 1);
    let sentiment = 'Neutral';
    let sentimentScore = 0.0;

    if (profitMargin > 0.15) {
      sentiment = 'Positive';
      sentimentScore = 0.35 + (companyHash % 30) / 100;
    } else if (profitMargin < 0.05) {
      sentiment = 'Negative';
      sentimentScore = -0.25 - (companyHash % 25) / 100;
    } else {
      sentiment = 'Neutral';
      sentimentScore = (companyHash % 20 - 10) / 100;
    }

    // Dynamic litigation risk
    const litigationRisk = ['Low', 'Medium', 'High'][companyHash % 3];
    const totalCases = companyHash % 5;
    const activeCases = Math.floor(totalCases * 0.6);

    // Dynamic industry analysis
    const industries = ['Technology', 'Manufacturing', 'Healthcare', 'Finance', 'Retail', 'Energy'];
    const industry = industries[companyHash % industries.length];

    const outlooks = ['Positive', 'Stable', 'Challenging'];
    const outlook = outlooks[companyHash % 3];

    const growthRates = ['5-8%', '8-12%', '2-5%', '10-15%', '0-3%'];
    const growthRate = growthRates[companyHash % growthRates.length];

    const positions = ['Leader', 'Strong Contender', 'Market Follower', 'Niche Player'];
    const marketPosition = positions[companyHash % positions.length];

    // Generate company-specific risk signals
    const riskSignals = [];
    const signalTemplates = [
      'Supply chain dependency and disruption risks',
      'Intense competition from {industry} companies',
      'Rising input costs affecting profitability',
      'Rapid technological changes requiring innovation',
      'Regulatory compliance challenges in {industry}',
      'Market volatility impacting revenue streams',
      'Currency fluctuation risks for international operations',
      'Talent retention and recruitment challenges'
    ];

    const numSignals = 2 + (companyHash % 4);
    for (let i = 0; i < numSignals; i++) {
      const template = signalTemplates[(companyHash + i) % signalTemplates.length];
      riskSignals.push(template.replace('{industry}', industry));
    }

    return {
      company,
      industry,
      research_summary: {
        news_sentiment: {
          sentiment,
          score: sentimentScore,
          total_articles_analyzed: 10 + (companyHash % 20)
        },
        litigation_data: {
          risk_assessment: litigationRisk,
          total_cases: totalCases,
          active_cases: activeCases
        },
        industry_analysis: {
          outlook,
          growth_rate: growthRate,
          market_position: marketPosition
        },
        risk_signals: riskSignals
      }
    };
  };

  const getSentimentColor = (sentiment) => {
    switch (sentiment) {
      case 'Positive': return { bg: '#dcfce7', text: '#166534', border: '#22c55e' };
      case 'Negative': return { bg: '#fef2f2', text: '#991b1b', border: '#ef4444' };
      default: return { bg: '#f9fafb', text: '#374151', border: '#6b7280' };
    }
  };

  const getRiskColor = (risk) => {
    switch (risk) {
      case 'Low': return { bg: '#dcfce7', text: '#166534', border: '#22c55e' };
      case 'Medium': return { bg: '#fef3c7', text: '#92400e', border: '#f59e0b' };
      case 'High': return { bg: '#fef2f2', text: '#991b1b', border: '#ef4444' };
      default: return { bg: '#f9fafb', text: '#374151', border: '#6b7280' };
    }
  };

  const getOutlookColor = (outlook) => {
    switch (outlook) {
      case 'Positive': return { bg: '#dcfce7', text: '#166534', border: '#22c55e' };
      case 'Challenging': return { bg: '#fef2f2', text: '#991b1b', border: '#ef4444' };
      default: return { bg: '#f9fafb', text: '#374151', border: '#6b7280' };
    }
  };

  if (loading) {
    return (
      <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', backgroundColor: '#f0f9ff' }}>
        <div style={{ textAlign: 'center' }}>
          <div style={{ 
            width: '48px', 
            height: '48px', 
            border: '4px solid #e5e7eb', 
            borderTop: '4px solid #2563eb', 
            borderRadius: '50%', 
            animation: 'spin 1s linear infinite',
            margin: '0 auto 16px'
          }}></div>
          <p style={{ fontSize: '18px', color: '#4b5563' }}>Loading research insights...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', backgroundColor: '#f0f9ff' }}>
        <div style={{ textAlign: 'center' }}>
          <div style={{ fontSize: '48px', marginBottom: '16px' }}>⚠️</div>
          <h2 style={{ fontSize: '24px', fontWeight: 'bold', color: '#dc2626', marginBottom: '8px' }}>Error Loading Research</h2>
          <p style={{ color: '#6b7280', marginBottom: '24px' }}>{error}</p>
          <SimpleButton onClick={() => window.location.reload()}>
            Try Again
          </SimpleButton>
        </div>
      </div>
    );
  }

  return (
    <div style={{ minHeight: '100vh', backgroundColor: '#f0f9ff' }}>
      {/* Header */}
      <div style={{ 
        background: 'linear-gradient(to right, #2563eb, #4f46e5)', 
        color: 'white', 
        padding: '32px 0',
        boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)'
      }}>
        <div style={{ maxWidth: '1280px', margin: '0 auto', padding: '0 16px' }}>
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
            <div>
              <h1 style={{ fontSize: '36px', fontWeight: 'bold', marginBottom: '8px', display: 'flex', alignItems: 'center' }}>
                <span style={{ marginRight: '12px' }}>📈</span>
                Research Insights
              </h1>
              <p style={{ fontSize: '20px', color: '#dbeafe' }}>
                {researchData?.company || 'Company'} - AI-Powered Market Research
              </p>
              {researchData?.industry && (
                <div style={{ marginTop: '8px' }}>
                  <span style={{ backgroundColor: 'rgba(255, 255, 255, 0.2)', padding: '4px 12px', borderRadius: '9999px', fontSize: '14px' }}>
                    🏭 {researchData.industry}
                  </span>
                </div>
              )}
            </div>
            <div style={{ display: 'flex', gap: '12px' }}>
              <SimpleButton
                onClick={() => navigate('/dashboard')}
                style={{ backgroundColor: 'white', color: '#2563eb' }}
              >
                📊 Back to Dashboard
              </SimpleButton>
              <SimpleButton
                onClick={() => navigate('/cam-preview')}
                style={{ backgroundColor: '#10b981', color: 'white' }}
              >
                📄 Generate CAM
              </SimpleButton>
            </div>
          </div>
        </div>
      </div>

      <div style={{ maxWidth: '1280px', margin: '0 auto', padding: '32px 16px' }}>
        {researchData && (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(400px, 1fr))', gap: '24px' }}>
            {/* News Sentiment */}
            <div style={{ 
              backgroundColor: 'white', 
              padding: '32px', 
              borderRadius: '16px', 
              boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
              border: '1px solid #e5e7eb'
            }}>
              <h3 style={{ fontSize: '20px', fontWeight: 'bold', color: '#111827', marginBottom: '24px', display: 'flex', alignItems: 'center' }}>
                <span style={{ marginRight: '12px', fontSize: '28px' }}>📰</span>
                News Sentiment Analysis
              </h3>
              <div style={{ marginBottom: '16px' }}>
                <div style={{ 
                  padding: '16px', 
                  borderRadius: '8px',
                  backgroundColor: getSentimentColor(researchData.research_summary.news_sentiment.sentiment).bg,
                  border: `1px solid ${getSentimentColor(researchData.research_summary.news_sentiment.sentiment).border}`
                }}>
                  <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '8px' }}>
                    <span style={{ fontSize: '14px', color: '#6b7280' }}>Sentiment</span>
                    <span style={{ 
                      fontWeight: 'bold',
                      color: getSentimentColor(researchData.research_summary.news_sentiment.sentiment).text
                    }}>
                      {researchData.research_summary.news_sentiment.sentiment}
                    </span>
                  </div>
                  <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '8px' }}>
                    <span style={{ fontSize: '14px', color: '#6b7280' }}>Sentiment Score</span>
                    <span style={{ fontWeight: 'bold', color: '#2563eb' }}>
                      {researchData.research_summary.news_sentiment.score.toFixed(2)}
                    </span>
                  </div>
                  <div style={{ fontSize: '12px', color: '#6b7280' }}>
                    Based on {researchData.research_summary.news_sentiment.total_articles_analyzed} news articles
                  </div>
                </div>
              </div>
            </div>

            {/* Litigation Analysis */}
            <div style={{ 
              backgroundColor: 'white', 
              padding: '32px', 
              borderRadius: '16px', 
              boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
              border: '1px solid #e5e7eb'
            }}>
              <h3 style={{ fontSize: '20px', fontWeight: 'bold', color: '#111827', marginBottom: '24px', display: 'flex', alignItems: 'center' }}>
                <span style={{ marginRight: '12px', fontSize: '28px' }}>⚖️</span>
                Litigation Analysis
              </h3>
              <div style={{ marginBottom: '16px' }}>
                <div style={{ 
                  padding: '16px', 
                  borderRadius: '8px',
                  backgroundColor: getRiskColor(researchData.research_summary.litigation_data.risk_assessment).bg,
                  border: `1px solid ${getRiskColor(researchData.research_summary.litigation_data.risk_assessment).border}`
                }}>
                  <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '8px' }}>
                    <span style={{ fontSize: '14px', color: '#6b7280' }}>Risk Assessment</span>
                    <span style={{ 
                      fontWeight: 'bold',
                      color: getRiskColor(researchData.research_summary.litigation_data.risk_assessment).text
                    }}>
                      {researchData.research_summary.litigation_data.risk_assessment}
                    </span>
                  </div>
                  <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '8px' }}>
                    <span style={{ fontSize: '14px', color: '#6b7280' }}>Total Cases</span>
                    <span style={{ fontWeight: 'bold', color: '#f59e0b' }}>
                      {researchData.research_summary.litigation_data.total_cases}
                    </span>
                  </div>
                  <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                    <span style={{ fontSize: '14px', color: '#6b7280' }}>Active Cases</span>
                    <span style={{ fontWeight: 'bold', color: '#ef4444' }}>
                      {researchData.research_summary.litigation_data.active_cases}
                    </span>
                  </div>
                </div>
              </div>
            </div>

            {/* Industry Analysis */}
            <div style={{ 
              backgroundColor: 'white', 
              padding: '32px', 
              borderRadius: '16px', 
              boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
              border: '1px solid #e5e7eb'
            }}>
              <h3 style={{ fontSize: '20px', fontWeight: 'bold', color: '#111827', marginBottom: '24px', display: 'flex', alignItems: 'center' }}>
                <span style={{ marginRight: '12px', fontSize: '28px' }}>🏭</span>
                Industry Analysis
              </h3>
              <div style={{ marginBottom: '16px' }}>
                <div style={{ 
                  padding: '16px', 
                  borderRadius: '8px',
                  backgroundColor: getOutlookColor(researchData.research_summary.industry_analysis.outlook).bg,
                  border: `1px solid ${getOutlookColor(researchData.research_summary.industry_analysis.outlook).border}`
                }}>
                  <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '8px' }}>
                    <span style={{ fontSize: '14px', color: '#6b7280' }}>Industry Outlook</span>
                    <span style={{ 
                      fontWeight: 'bold',
                      color: getOutlookColor(researchData.research_summary.industry_analysis.outlook).text
                    }}>
                      {researchData.research_summary.industry_analysis.outlook}
                    </span>
                  </div>
                  <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '8px' }}>
                    <span style={{ fontSize: '14px', color: '#6b7280' }}>Growth Rate</span>
                    <span style={{ fontWeight: 'bold', color: '#2563eb' }}>
                      {researchData.research_summary.industry_analysis.growth_rate}
                    </span>
                  </div>
                  <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                    <span style={{ fontSize: '14px', color: '#6b7280' }}>Market Position</span>
                    <span style={{ fontWeight: 'bold', color: '#7c3aed' }}>
                      {researchData.research_summary.industry_analysis.market_position}
                    </span>
                  </div>
                </div>
              </div>
            </div>

            {/* Risk Signals */}
            <div style={{ 
              backgroundColor: 'white', 
              padding: '32px', 
              borderRadius: '16px', 
              boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
              border: '1px solid #e5e7eb'
            }}>
              <h3 style={{ fontSize: '20px', fontWeight: 'bold', color: '#111827', marginBottom: '24px', display: 'flex', alignItems: 'center' }}>
                <span style={{ marginRight: '12px', fontSize: '28px' }}>🚨</span>
                Risk Signals
              </h3>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                {researchData.research_summary.risk_signals && researchData.research_summary.risk_signals.length > 0 ? (
                  researchData.research_summary.risk_signals.map((signal, index) => (
                    <div key={index} style={{ 
                      display: 'flex',
                      alignItems: 'flex-start',
                      gap: '12px',
                      padding: '12px',
                      backgroundColor: '#fef2f2',
                      borderRadius: '8px',
                      borderLeft: '4px solid #ef4444'
                    }}>
                      <div style={{ fontSize: '20px' }}>⚠️</div>
                      <p style={{ fontSize: '14px', color: '#374151', lineHeight: '1.5' }}>{signal}</p>
                    </div>
                  ))
                ) : (
                  <div style={{ textAlign: 'center', padding: '32px' }}>
                    <div style={{ fontSize: '48px', marginBottom: '16px' }}>✅</div>
                    <p style={{ color: '#6b7280' }}>No significant risk signals identified</p>
                  </div>
                )}
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default SimpleResearchInsights;
